model.cr_project.copy_into_runner.raw_code:
{% set pre_hooks = [
    "{{ copy_into(source_name=var('source_name', 'salesforce'), api=var('api', 'User'), file_format=var('copy_into_file_format', '(type = json)'), on_error=var('copy_into_on_error', 'CONTINUE'), force=var('copy_into_force', false), truncate=var('copy_into_truncate', true)) }}"
] %}

{{
    config(
        materialized='view',
        tags=['operation', 'copy_into'],
        pre_hook=pre_hooks
    )
}}

select 
       1 as marker,
    '{{ env_var("DBT_LANDING_DB", "TIMN_DB_BLUE") }}' as landing_db,
       '{{ var("source_name", "salesforce") }}' as source_name,
       '{{ copy_into_landing_schema(var("source_name", "salesforce")) }}' as landing_schema,
    '{{ var("api", "User") }}' as api,
    '{{ copy_into_table_name(var("api", "User")) }}' as table_name,
    '{{ copy_into_source_stage(env_var("DBT_LANDING_DB", "TIMN_DB_BLUE"), var("source_name", "salesforce")) }}' as source_stage,
       '{{ var("copy_into_file_format", "(type = json)") }}' as file_format,
        '{{ var("copy_into_truncate", true) }}' as truncate_before_copy,
        '{{ copy_into_pattern(var("source_name", "salesforce"), var("api", "User")) }}' as pattern,
        $$ {{ copy_into_sql(
            var("source_name", "salesforce"),
            var("api", "User"),
            none,
            var("copy_into_file_format", "(type = json)"),
            copy_into_pattern(var("source_name", "salesforce"), var("api", "User")),
            var("copy_into_on_error", "CONTINUE"),
            var("copy_into_force", false),
            var("copy_into_truncate", true)
             ) }} $$ as copy_statement,
       current_timestamp() as copy_into_executed_at
from (select 1) as marker

