model.dbt_project_evaluator.fct_document.raw_code:
with

models as (
    select * from {{ ref('int_all_graph_resources') }}
    where resource_type = 'model'
    and is_excluded = cast(0 as {{ dbt.type_boolean() }})
),

conversion as (
    select
        resource_id,
        case when is_described = cast(1 as {{ dbt.type_boolean() }}) then 1 else 0 end as is_described_model,
        {% for model_type in var('model_types') %}
            case when model_type = '{{ model_type }}' then 1.0 else NULL end as is_{{ model_type }}_model,
            case when is_described = cast(1 as {{ dbt.type_boolean() }}) and model_type = '{{ model_type }}' then 1.0 else 0 end as is_described_{{ model_type }}_model{% if not loop.last %},{% endif %}
        {% endfor %}

    from models
),

final as (
    select
        {{ dbt.current_timestamp() if target.type != 'trino' else 'current_timestamp(6)' }} as measured_at,
        cast(count(*) as {{ dbt.type_int() }}) as total_models,
        cast(sum(is_described_model) as {{ dbt.type_int() }}) as documented_models,
        round(sum(is_described_model) * 100.00 / count(*), 2) as documentation_coverage_pct,
        {% for model_type in var('model_types') %}
            round(
                {{ dbt_utils.safe_divide(
                    numerator = "sum(is_described_" ~ model_type ~ "_model) * 100", 
                    denominator = "count(is_" ~ model_type ~ "_model)"
                ) }}
            , 2) as {{ model_type }}_documentation_coverage_pct{% if not loop.last %},{% endif %}
        {% endfor %}

    from models
    left join conversion
    on models.resource_id = conversion.resource_id
)

select * from final

model.dbt_project_evaluator.fct_duplicat.raw_code:
with sources as (
    select
        resource_name,
        case 
            -- if you're using databricks but not the unity catalog, database will be null
            when {{ dbt_project_evaluator.quote_identifier('database') }} is NULL then {{ dbt.concat([dbt_project_evaluator.quote_identifier('schema'), "'.'", "identifier"]) }}
            else {{ dbt.concat([dbt_project_evaluator.quote_identifier('database'), "'.'", dbt_project_evaluator.quote_identifier('schema'), "'.'", "identifier"]) }}
        end as source_db_location 
    from {{ ref('int_all_graph_resources') }}
    where resource_type = 'source'
    and is_excluded = cast(0 as {{ dbt.type_boolean() }})
    {% if target.type not in ['fabric'] %}
    -- we order the CTE so that listagg returns values correctly sorted for some warehouses
    order by 1, 2
    {% endif %}
),

source_duplicates as (
    select
        source_db_location,
        {{ dbt.listagg(
            measure = 'resource_name',
            delimiter_text = "', '",
            order_by_clause = 'order by resource_name' if target.type in ['snowflake','redshift','duckdb','trino','fabric'])
        }} as source_names
    from sources
    group by source_db_location
    having count(*) > 1
)

select * from source_duplicates

{{ filter_exceptions() }}

