        {%- else %}
        SELECT {{ automate_dv.prefix(source_cols, 'rr') }},
        {%- endif %}
               ROW_NUMBER() OVER(
                   PARTITION BY {{ automate_dv.prefix([src_pk], 'rr') }}
                   ORDER BY {{ automate_dv.prefix([src_ldts], 'rr') }}
               ) AS row_number
        FROM {{ ref(src) }} AS rr
        WHERE {{ automate_dv.multikey(src_pk, prefix='rr', condition='IS NOT NULL') }}
