{% macro smoke_test_verified_query_sql_against_base_tables(sv_name='opportunity_field_history') %}

  {{ log('=== Verified Query SQL Smoke Test (base table rewrite) ===', info=true) }}
  {{ log('[NOTE: This rewrites __logical_table markers to physical FQNs and runs', info=true) }}
  {{ log(' against base tables. This is a warehouse SQL smoke test ONLY — it does', info=true) }}
  {{ log(' NOT validate semantic-layer or Cortex Analyst behavior.]', info=true) }}
  {{ log('', info=true) }}

  {% set spec = get_semantic_view_spec(sv_name) %}
  {% set fqn_prefix = var('table_database', target.database) ~ '.' ~ var('table_schema', target.schema) ~ '.' %}

  {# ── Build logical-to-physical table map dynamically from spec ── #}
  {# Sort by name length descending to avoid partial matches during replacement #}
  {% set table_entries = [] %}
  {% for table in spec.tables %}
    {% do table_entries.append({
      'logical': '__' ~ table.name,
      'physical': fqn_prefix ~ table.base_table.table
    }) %}
  {% endfor %}

  {# Sort by logical name length descending (longest first) #}
  {% set sorted_entries = table_entries | sort(attribute='logical', reverse=true) %}

  {{ log('Table mapping:', info=true) }}
  {% for entry in sorted_entries %}
    {{ log('  ' ~ entry.logical ~ ' -> ' ~ entry.physical, info=true) }}
  {% endfor %}
  {{ log('', info=true) }}

  {% set vqs = spec.verified_queries %}
  {% set ns = namespace(pass_count=0, warn_count=0, fail_count=0) %}

  {% for vq in vqs %}

    {{ log('--- Smoke test: ' ~ vq.name ~ ' ---', info=true) }}

    {# Replace logical table markers with physical FQNs using namespace for loop safety #}
    {% set ns_sql = namespace(sql=vq.sql) %}
    {% for entry in sorted_entries %}
      {% set ns_sql.sql = ns_sql.sql | replace(entry.logical, entry.physical) %}
    {% endfor %}

    {# Execute the rewritten SQL #}
    {% set result = run_query(ns_sql.sql) %}

    {% if result and result.rows | length > 0 %}
      {{ log('PASS: ' ~ result.rows | length ~ ' rows returned', info=true) }}
      {% set ns.pass_count = ns.pass_count + 1 %}
    {% else %}
      {{ log('WARN: 0 rows returned (may be expected for time-filtered queries)', info=true) }}
      {% set ns.warn_count = ns.warn_count + 1 %}
    {% endif %}

    {{ log('', info=true) }}

  {% endfor %}

  {# ── Summary ── #}
  {% set total = vqs | length %}
  {{ log('=== Smoke Test Summary ===', info=true) }}
  {{ log('Total: ' ~ total ~ ' | PASS: ' ~ ns.pass_count ~ ' | WARN: ' ~ ns.warn_count ~ ' | FAIL: ' ~ ns.fail_count, info=true) }}
  {{ log('Executed: ' ~ (ns.pass_count + ns.warn_count + ns.fail_count) ~ '/' ~ total ~ ' queries', info=true) }}

