    {{ return("table") }}
  {% elif tmp_relation_type == "view" %}
    {{ return("view") }}
  {% elif tmp_relation_type == "transient" %}
    {{ return("transient") }}
  {% elif strategy in ("default", "merge", "append", "insert_overwrite") %}
