    {%- set sid_column_expression = sid_column_expression ~ ", '|', " ~ dbt_versent_dimensional_automate.effective_date_column('from') %}
{%- endif %}
{%- set sid_column_expression = sid_column_expression ~ ")" %}

{%- if hash_algorithm == "automate_dv.hash" %}
    {%- set hash_expression = automate_dv.hash(sid_column_expression,sid) %}
{%- else %}
    {%- set hash_expression = hash_algorithm.replace('<column>', sid_column_expression) %}
{%- endif %}

with 
    source as (
        select
            {{ business_key}},
            {{ dbt_versent_dimensional_automate.payload_columns(payload)}},
            -- hashdiff
                CAST(UPPER(md5(CONCAT(
                {%- for col in payload %}
                IFNULL(NULLIF(TRIM(CAST({{col}} AS VARCHAR(16))), ''), '^^'){% if not loop.last %}, '||',{% endif %}
                {%- endfor %}
                {% if record_action|length > 0 %}
                , '||',{{ record_action }}
                {% endif %}            
                ))) AS binary) as hashdiff,
            {% if record_action|length > 0 %}
            {{ record_action }},
            {% endif %}
            {% if type2 %}
            {{ type2_columns(business_key, type2) }}
            {% endif %}
            {{ dbt_versent_dimensional_automate.audit_columns() }}
        from 
        {{ ref(source) }}
        where
          -- remove the ghost as_of_date from records other than the ghost
            (TO_DATE(as_of_date) = '1900-01-01' and {{business_key}} = '00000000000000000000000000000000') or
            TO_DATE(as_of_date) <> '1900-01-01'        

    ),
    final as (
        select
        {%- if hash_algorithm == "automate_dv.hash" %}
            {{ hash_expression }},
        {%- else %}
            cast({{ hash_expression }} as {{ sid_type }}) as {{ sid }},
        {%- endif %}
            {{ business_key }},
            {%- for col in payload %}
            {{col}},
            {%- endfor %}
            {%- if type2 -%}
            -- cdc columns
                {{ dbt_versent_dimensional_automate.effective_date_column('from') }},
                {{ dbt_versent_dimensional_automate.effective_date_column('to') }},
                is_current,
            {%- endif -%}
            -- audit columns
            {{ dbt_versent_dimensional_automate.audit_columns() }}
        from
            source
        where
            -- row_num = 1 and 
            1=1
    )
select 
    *
from final
{%- endmacro %}

{% macro dimension_columns(dimensions) -%}

{%- if dimensions.get('dimensions') -%}
    {%- for dim in dimensions['dimensions'] -%}
        {%- for dim_name, properties in dim.items() -%}
        {%- set dim_table_name = dimension_table_name(dim_name) -%}                
        {%- if properties.get('role_playing') -%}
            {%- for alias, _ in properties['role_playing'].items() %}
            {{ alias }}.{{ sid_name(dim_name) }} as {{ sid_name(alias) }},
            {% if var("include_business_keys") == 'y' -%}
            {{ alias }}.{{ business_key_name(dim_name) }} as {{ business_key_name(alias) }},
            {%- endif -%}
            {%- endfor -%}
        {%- else -%}
            {{ dim_table_name }}.{{ sid_name(dim_name) }} as {{ sid_name(dim_name) }},
            {% if var("include_business_keys") == 'y' -%}
            {{ dim_table_name }}.{{ business_key_name(dim_name) }} as {{ business_key_name(dim_name) }},
            {%- endif -%}                        
        {%- endif -%}
        {%- endfor -%}
    {%- endfor -%}
{%- endif %}

{%- endmacro %}

{% macro dimension_table_name(
    name
    ) -%}
    {%- set dimension_name = var("dimension_table_name")|replace('<name>',name) -%}

    {{ dimension_name }}

{%- endmacro %}

macro.dbt_versent_dimensional_automate.e.macro_sql:
{%- macro early_date() -%}
    cast('1900-01-01 00:00:01'   as timestamp)
{%- endmacro %}

{% macro effective_date_column(
    type
    ) -%}
        {%- if type == 'from' -%}
            {{ var('effective_from_name', 'effective_from') }}
        {%- elif type == 'to' -%}
            {{ var('effective_to_name', 'effective_to') }}
        {%- else -%}
            {{ exceptions.raise_compiler_error("Invalid type passed to effective_date_column. Expecting 'from' or 'to'.") }}
        {%- endif -%}
{%- endmacro %}

{%- macro effective_from_datetime(
    business_key,
    as_of_date_source
    ) -%}
    iff(
    -- previous_date
        {{ dbt_versent_dimensional_automate.previous_date(business_key, as_of_date_source)}}
        is null, 
        {{ dbt_versent_dimensional_automate.early_date() }}, 
        as_of_date)


    {%- endmacro %}

{%- macro effective_to_datetime(
    business_key,
    as_of_date_source
    ) -%}
    coalesce(
        -- next_date - 1 very small bit
            {{ dbt_versent_dimensional_automate.next_date(business_key, as_of_date_source)}} 
            -- {{ target.type }}
            {% if target.type == "databricks" %}
            - INTERVAL 1 microsecond     
            {% elif target.type == "snowflake" %}          
            - INTERVAL '1 MICROSECONDS'
            {% endif %}, 
        {{ dbt_versent_dimensional_automate.late_date() }}
        )

    {%- endmacro%}

macro.dbt_versent_dimensional_automate.i.macro_sql:
{%- macro is_current(
    business_key,
    as_of_date_source
    ) -%}
    iff(
        -- next_date
        {{ dbt_versent_dimensional_automate.next_date(business_key, as_of_date_source)}} is null,
        true,
        false
    )    
    {%- endmacro%}

macro.dbt_versent_dimensional_automate.j.macro_sql:
{% macro join_dimensions(dimensions, type) -%}

{%- if type == 'type2' -%}
    {%- set dim_as_of_date = dimensions.get('dimension_as_of_date') -%}      
{%- endif -%}

{%- if dimensions.get('dimensions') -%}
    {%- for dim in dimensions['dimensions'] %}
        {% for dim_name, properties in dim.items() %}
            {%- set dim_table_name = dimension_table_name(dim_name) -%}
            {%- if properties.get('role_playing') -%}
            {% for alias, _ in properties['role_playing'].items() %}
            left join 
                {{ dim_table_name }} AS {{ alias }}
                    on bridge.{{ business_key_name(alias) }} = {{ alias }}.{{ properties['join_key'] }}
                    {% if type == 'type2' and dim_as_of_date -%}
                    and bridge.{{ dim_as_of_date }} between {{ alias }}.{{ effective_date_column('from') }} and {{ alias }}.{{ effective_date_column('to') }} 
                {%- endif -%}                        
            {%- endfor -%}
            {%- else -%}
            left join 
                {{ dim_table_name }}
                    on bridge.{{ properties['join_key'] }} = {{ dim_table_name }}.{{ properties['join_key'] }}
                    {% if type == 'type2' and dim_as_of_date -%}
                    and bridge.{{ dim_as_of_date }} between {{ dim_table_name }}.{{ effective_date_column('from') }} and {{ dim_table_name }}.{{ effective_date_column('to') }} 
                {%- endif -%}
            {%- endif -%}
        {%- endfor -%}
    {%- endfor -%}
{% endif %}    
{%- endmacro %}

macro.dbt_versent_dimensional_automate.l.macro_sql:
{%- macro late_date() -%}
