    business_key,
    type2
    ) -%}
    -- type2 columns
            {%- set as_of_date_source = type2.as_of_date %}
            {%- set effective_from = var('effective_from_name', 'effective_from') -%}
            {%- set effective_to = var('effective_to_name', 'effective_to') %}                  
            {{ dbt_versent_dimensional_automate.effective_from_datetime(business_key, as_of_date_source)}}  as {{ effective_from }},
            {{ dbt_versent_dimensional_automate.effective_to_datetime(business_key, as_of_date_source)}}  as {{ effective_to }},
            {{ dbt_versent_dimensional_automate.is_current(business_key, as_of_date_source)}}  as is_current,

{%- endmacro %}

macro.versent_dbt_automatedv_overrides_p.macro_sql:
{% macro cbc(
    hash_key,
    hub_bkey,
    hub,
    pit,
    satellites,
    payload,
    derivations
    ) -%}
with 
    hub as (
        select 
            {{hash_key}},
            {{hub_bkey}},
            record_source
        from {{ ref(hub) }}
    ),
    pit as (
        select 
            *
        from
                    {{ ref(pit)}}
    ),
    -- satellites
    {%- for sat in satellites %}
    {{sat}} as (
        with
            {{ sat }}_data as (  
                select 
                    {{ satellites[sat]['pk'] }},
                    {{ satellites[sat]['ldts'] }},
                    -- payload
                    {% set sat_payload = satellites[sat]['payload'] %}
                    {% if sat_payload %}  
                        {{ versent_dbt_automatedv_overrides_private.mac_payload(sat_payload)}}
                    {% endif %}
                from 
                    {{ ref(sat)}}
            )
            {%- set lookups = satellites[sat].get('lookups', {}) %} 
            {%- for lookup in lookups %}
            ,{{ lookup}} as (  
                select
                    {{ lookups[lookup]['bk'] ~ ' as bk_' ~ lookup}},
                    {% set lookup_payload = lookups[lookup]['payload'] %}
                    {{ versent_dbt_automatedv_overrides_private.mac_payload(lookup_payload)}}
                from
                    {{ ref(lookup)}}
            )
            {%- endfor %}
            ,final as (  
                select 
                    *
                from 
                    {{ sat }}_data  
                        {%- set lookups = satellites[sat].get('lookups', {}) %}
                        {%- for lookup in lookups %}
                        left join
                        {{ lookup}} 
                            on
                                {{sat}}_data.{{ lookups[lookup]['sat_bk'] if 'sat_bk' in lookups[lookup] else lookups[lookup]['bk'] }} = {{ 'bk_' ~ lookup }}
                        {%- endfor %}
            )

            select
                *
            from 
                final
    )
    {%- if not loop.last %},{% endif %}  
    {%- endfor %}
    ,get_sats as ( 
        select 
            hub.{{hash_key}},
            hub.{{hub_bkey}},
            pit.as_of_date
            {%- for sat in satellites %}    
                {% set sat_payload = satellites[sat]['payload'] %}
                {% if sat_payload %}
                ,{{ versent_dbt_automatedv_overrides_private.mac_payload(sat_payload)}}
                {% endif %}
                {%- set lookups = satellites[sat].get('lookups', {}) %}
                {%- for lookup in lookups %}
                    {% set lookup_payload = lookups[lookup]['payload'] %}
                    ,{{ versent_dbt_automatedv_overrides_private.mac_payload(lookup_payload)}}
                {%- endfor %}
            {%- endfor %}  
            ,current_timestamp() as load_datetime
            ,hub.record_source    
        from
            hub
            join 
                pit 
                    on
                        hub.{{hash_key}} = pit.{{hash_key}}
                -- satellites
                    {%- for sat in satellites %}
                    left join
                        {{sat}}
                            on
                                pit.{{hash_key}} = {{sat}}.{{satellites[sat]['pk']}} and  
                                pit.{{satellites[sat]['pit_ldts']}} = {{sat}}.{{satellites[sat]['ldts']}}
                    {%- endfor %}
    )
    {%- if derivations %} 
    ,derivations as (
        select
            {{ versent_dbt_automatedv_overrides_private.mac_payload(derivations)}},                 
            * 
        from
            get_sats
    )
    {%- endif %}
    ,final as (
        select
            *
        from
            {% if derivations %}derivations{% else %}get_sats{% endif %}
    )
select
    *
from
    final 
{%- endmacro %}

{% macro hk_ghost(column_name) -%}
coalesce (
    {{column_name}},
    {{ hk_ghost_default()}}
    ) as {{ column_name }}
{%- endmacro %}

{%- macro int(models) -%}
{%- set model = models[0] %}
{%- set desc = model['description'] %}
{%- set src = desc.split('source:')[1] %}
{%- set table = src.split()[0] %}
{%- set constraints = model['constraints'] %}
SELECT  
    {%- set columns = model['columns'] %}
    {%- for column in columns %}
    {%- set column_description = column['description'] %}
    {%- set column_name = column['name'] %}
    {%- if 'source' in column_description %}
    {%- set col_source = column_description.split(':')[1]%}
    {%- else %}
    {%- set col_source = table + '.' + column_name %}
    {%- endif %}
    {{col_source}} as {{ column_name}}{{ ", " if not loop.last else "" }}

    {%- endfor %}
from 
    {{ ref(table) }}
    {%- for constraint in constraints| selectattr('type','equalto', 'foreign_key') %}
    left join 
        {%- set expression = constraint['expression'] %}  
        {%- set no_schema = expression.split('.')[1] %}
        {%- set table_name = no_schema.split('(')[0]|trim %}
        {{ ref(table_name)}}
        on 
            {{table}}.{{ constraint['columns'][0]}} = {{table_name}}.{{no_schema.split('(')[1].split(',')[0]}}
    {%- endfor %}
{%- endmacro -%}

{%- macro mac_payload(
    pPayload
) -%}
    {%- for col in pPayload %}
        {{ col }}{%- if not loop.last %},{% endif -%}
    {%- endfor %}
{%- endmacro %}

{%- macro mac_payload_cols(
    pPayload
) -%}
    {%- for col in pPayload %}
        {{ col}},
    {%- endfor %}
{%- endmacro %}

{% macro pit(
    hub,
    hash_key,
    business_key,
    as_of_dates_table,
    as_of_date,
    satellites,
    record_source,
    load_datetime
    ) -%}
with 
{%- if as_of_dates_table|length == 0 %} 
-- ##### generated_as_of_dates
{%- for sat in satellites %}
    {{sat}}_as_of_date as (
        select 
            {{ satellites[sat]['pk'] }},
            {{ satellites[sat]['ldts'] }} as as_of_date
        from 
            {{ ref(sat)}}
    ),
{%- endfor %}
    union_sat_as_of_dates as (
    {%- for sat in satellites %}        
        select 
            * 
        from
            {{sat}}_as_of_date
        {% if not loop.last %}union{% endif %}
    {%- endfor %}
    ),
    generated_as_of_dates as (
        select distinct *
        from union_sat_as_of_dates
    ),
-- ##### generated_as_of_dates
{%- endif %} 
    rows_as_of_dates as (
        select
            hub.{{hash_key}},
            {%- if business_key|length > 0 %} 
            hub.{{business_key}}, 
            {%- endif %}
            {%- if as_of_date|length > 0 %}
            as_of_dates.{{as_of_date}} as as_of_date
            {%- else %}
            as_of_dates.as_of_date
            {%- endif %}
        from
            {{ ref(hub)}} hub
        left join
            {%- if as_of_dates_table|length > 0 %}            
            {{ ref(as_of_dates_table)}} as_of_dates
            {%- else %}
            generated_as_of_dates as_of_dates
            {%- endif %}             
            on hub.{{hash_key}}  = as_of_dates.{{hash_key}}
          
    ),
    {%- for sat in satellites %}
    {{sat}}_effective_dates AS (
        select
            {{hash_key}},
            {{ satellites[sat]['ldts'] }},
            CASE 
                WHEN ROW_NUMBER() OVER (PARTITION BY {{hash_key}} ORDER BY {{ satellites[sat]['ldts'] }}) = 1 
                THEN TO_TIMESTAMP('1900-01-01 00:00:00')
                ELSE {{ satellites[sat]['ldts'] }}
            END AS effective_from,
            DATEADD(
            'millisecond', -1,
            LEAD({{ satellites[sat]['ldts'] }}, 1, TO_TIMESTAMP('2999-01-01 00:00:01')) OVER (
                PARTITION BY {{hash_key}}
                ORDER BY {{ satellites[sat]['ldts'] }}
            )
            ) AS effective_to
        FROM
            {{ ref(sat)}}
    ),
    {%- endfor %}          
    row_sats as (
        select
            rows_as_of_dates.{{hash_key}},
            {%- if business_key|length > 0 %} 
            rows_as_of_dates.{{business_key}}, 
            {%- endif %}
            rows_as_of_dates.as_of_date,
            -- ghost
            {{ versent_dbt_automatedv_overrides_private.hk_ghost_default()}},
            cast('1900-01-01 00:00:00' as timestamp) as early_date,            
            {%- for sat in satellites %}
            {{sat}}_src.{{ satellites[sat]['pk'] }} as {{sat}}_pk,
            {{sat}}_src.{{ satellites[sat]['ldts'] }} as {{sat}}_ldts{% if not loop.last %},{% endif %}
            {%- endfor %}  
        from
            rows_as_of_dates
        {%- for sat in satellites %}
            left join
                 {{sat}}_effective_dates as {{sat}}_src
                on rows_as_of_dates.{{hash_key}} = {{sat}}_src.{{ satellites[sat]['pk'] }}
                and rows_as_of_dates.as_of_date between {{sat}}_src.effective_from
                    and {{sat}}_src.effective_to                        
        {%- endfor %}       

    ),
    final as (
        select
            {{hash_key}},
            {%- if business_key|length > 0 %} 
            {{business_key}}, 
            {%- endif %}
            coalesce(as_of_date, early_date) as as_of_date,
            {%- if record_source|length > 0 %} 
            '{{record_source}}' as record_source, 
            {%- endif %}
            {%- if load_datetime|length > 0 %} 
            {{load_datetime}} as load_datetime, 
            {%- endif %}
            {%- for sat in satellites %}            
                coalesce({{sat}}_pk , hk_ghost) as {{sat}}_pk,
                coalesce({{sat}}_ldts, early_date) as {{sat}}_ldts{% if not loop.last %},{% endif %}
            {%- endfor %}    
        from
            row_sats 
    )    
select
    *
from
    final
{%- endmacro %}

{% macro pit_as_of_date(
    satellites
    ) -%}
with
{%- for sat in satellites %}
    {{sat}} as (
        select 
            {{ satellites[sat]['pk'] }},
            {{ satellites[sat]['as_of_date'] }} as as_of_date
        from 
            {{ ref(sat)}}
    ),
{%- endfor %}

    union_sat_as_of_dates as (
    {%- for sat in satellites %}        
        select 
            * 
        from
            {{sat}}
        {% if not loop.last %}union{% endif %}
    {%- endfor %}
    ),
    final as (
        select distinct *
        from union_sat_as_of_dates
    )

    select 
        *
    from 
        final
{%- endmacro %}

{% macro sat(
    src_pk,
    business_key,
    src_hashdiff,
    src_payload,
    src_extra_columns,
    src_eff,
    src_ldts,
    src_source,
    source_model
    ) -%}
 
{% set lower_src_payload = src_payload | map('lower') | list %}
{% if 'record_action' in lower_src_payload %}
    {% set record_action_fld_name = src_payload[lower_src_payload.index('record_action')] %}
{%- endif -%}
 
with
    automate_dv_sat as (
        {{ automate_dv.sat(
            src_pk=src_pk,
                src_hashdiff=src_hashdiff,
                src_payload=src_payload,
                src_extra_columns=src_extra_columns,
                src_eff=src_eff,
                src_ldts=src_ldts,
                src_source=src_source,
                source_model=source_model
                            ) }}
    ),
    {%- if business_key|length > 0 %} 
    bk as (
        select
            distinct
            {{ src_pk }},
            {{ business_key }}
        from
            {{ ref(source_model)}}
    ),
    {%- endif %}
    final as (
        select
            {%- if business_key|length > 0 %} 
            coalesce(bk.{{business_key}}, '{{ var('bk_ghost') }}') as {{business_key}},
            {%- endif %}
            automate_dv_sat.*
            {%- if record_action_fld_name %} 
                except({{ record_action_fld_name }}),
                coalesce({{ record_action_fld_name }}, 'INSERT') as {{ record_action_fld_name }}
            {%- endif %}
        from
            automate_dv_sat
        {%- if business_key|length > 0 %} 
        left join
            bk
                on automate_dv_sat.{{src_pk}} = bk.{{src_pk}}
        {%- endif %}   
    )
select
    *
from
    final

{%- endmacro %}

{%- macro t_link(src_pk, src_fk, src_payload, src_extra_columns, src_eff, src_ldts, src_source, source_model) -%}

with t_lnk as (
{{ automate_dv.nh_link(
    src_pk=src_pk,
    src_fk=src_fk,
    src_payload=src_payload,
    src_extra_columns=src_extra_columns,
    src_eff=src_eff,
    src_ldts=src_ldts,
    src_source=src_source,
    source_model=source_model
    ) }}
)
select 
    t_lnk.* except(
            {%- for col in src_fk %}
            {{col}}{% if not loop.last %},{% endif %}
            {%- endfor %}
    ) ,
    {%- for col in src_fk %}
    if(
        string({{col}})='CD9E459EA708A948D5C2F5A6CA8838CF', 
        cast('{{ var('bk_ghost') }}' as binary),
        {{col}}
     ) as {{col}}{% if not loop.last %},{% endif %}
    {%- endfor %}    

from
    t_lnk
                    
 
{%- endmacro -%}

